#!/usr/bin/env bash
# Package secsdk as a wheel next to the function app and write requirements.txt.
# Run before `func azure functionapp publish` or `azd deploy`.
set -euo pipefail
cd "$(dirname "$0")"

rm -rf wheels
mkdir -p wheels
uv build --wheel --out-dir wheels ../../packages/secsdk >/dev/null
wheel=$(cd wheels && ls secsdk-*.whl)

cat > requirements.txt <<EOF
# Generated by build.sh - do not edit by hand.
# Do not include azure-functions-worker; the platform manages it.
azure-functions>=2.3.0
azure-identity>=1.17
azure-monitor-opentelemetry>=1.6
opentelemetry-api>=1.27
./wheels/${wheel}
EOF

echo "Built wheels/${wheel} and requirements.txt"
